#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum LeftView {
    Files,
    Git,
    Run,
}

impl LeftView {
    const ALL: [LeftView; 3] = [LeftView::Files, LeftView::Git, LeftView::Run];

    fn name(self) -> &'static str {
