let over = |surface: u32, color: gpui_kit::Hsla| {
    let c: gpui_kit::Rgba = color.into();
    [(16, c.r), (8, c.g), (0, c.b)]
        .into_iter()
        .fold(0u32, |rgb, (shift, channel)| {
            let s = ((surface >> shift) & 0xff) as f32 / 255.;
            let v = s * (1. - c.a) + channel * c.a;
            rgb | ((v * 255.).round() as u32) << shift
        })
};
